{
  "claims": [
    {
      "claim": "针对“无法回充，找不到充电座”问题，适用资料片段[1]。",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "引用格式标注和问题场景描述，非事实性论断。"
    },
    {
      "claim": "按顺序执行以下步骤，任一步骤解决后即可结束排查。",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]开头明确“按顺序执行以下步骤，任一步骤解决后即可结束排查”。"
    },
    {
      "claim": "步骤1：确认基站电源指示灯亮起，基站靠墙放置，前方1.5米、两侧0.5米内无障碍物和强反光物体。",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "与片段[1]步骤1原文一致。"
    },
    {
      "claim": "步骤2：关机后用干燥软布轻擦主机充电极片与基站弹片，去除灰尘和毛发，不要使用湿布或金属工具；平台禁止用金属工具刮擦或短接触点。",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "与片段[1]步骤2及安全提示一致。"
    },
    {
      "claim": "步骤3：移开基站前方的地毯边缘、拖鞋和数据线等杂物，确保机器人能从任意方向接近基站。",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "与片段[1]步骤3原文一致。"
    },
    {
      "claim": "步骤4：把机器人放到基站前约1米处，按机身回充键重试。",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "与片段[1]步骤4前半句一致。"
    },
    {
      "claim": "步骤4：仍失败请结束自助排查并联系售后。",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "属于“请联系售后”类兜底话术，非事实性论断。"
    },
    {
      "claim": "以上步骤全部执行后问题仍存在的，请停止自助排查并联系官方售后。",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "属于“请联系售后”类兜底话术，非事实性论断。"
    }
  ]
}

{
  "claims": [
    {
      "claim": "RC-S200 吸力下降排查适用于问题“吸力变小了，扫不干净”，按顺序执行以下步骤，任一步骤解决后即可结束排查",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "说明书[1]第一句明确给出适用问题和执行规则。"
    },
    {
      "claim": "步骤1（清空尘盒）：取出尘盒倒空垃圾，尘盒装满会直接导致吸力明显下降",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "与说明书[1]步骤1内容一致。"
    },
    {
      "claim": "步骤2（清理滤网）：取出海帕滤网轻拍除尘，滤网只能干洗晾干，严禁水洗后立即装回",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "与说明书[1]步骤2内容一致。"
    },
    {
      "claim": "步骤3（检查吸尘口堵塞）：翻转机器检查吸尘口是否被纸团、袜子等大件异物堵住并清理",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "与说明书[1]步骤3内容一致。"
    },
    {
      "claim": "以上步骤全部执行后问题仍存在的，请停止自助排查并联系官方售后",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "属于“联系售后”类兜底话术，不构成可验证的事实论断。"
    }
  ]
}

{
  "claims": [
    {
      "claim": "RC-M500 型号报错 E07 水路异常时，按顺序执行以下步骤",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]开头明确说明适用于RC-M500错误码E07水路异常排查，并按顺序执行以下步骤。"
    },
    {
      "claim": "E07 表示供水异常",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤1原文写明“E07 表示供水异常”。"
    },
    {
      "claim": "先确认清水箱水量并重新安装到位",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤1写明“先确认清水箱水量并重新安装到位”。"
    },
    {
      "claim": "温水冲洗清水箱出水阀",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤2写明“温水冲洗清水箱出水阀”。"
    },
    {
      "claim": "硬水地区建议每月除垢一次",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤2写明“硬水地区建议每月除垢一次”。"
    },
    {
      "claim": "重启基站后手动触发清洗验证",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤3写明“重启基站后手动触发清洗验证”。"
    },
    {
      "claim": "E07 复现请联系售后",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "属于“请联系售后”类兜底话术，非事实性内容。"
    },
    {
      "claim": "错误码 E07（水路异常）的原因为清水箱缺水、未装到位或出水阀被水垢堵塞",
      "verdict": "supported",
      "evidence_index": 2,
      "reason": "片段[2]错误码速查中写明E07原因为“清水箱缺水、未装到位或出水阀被水垢堵塞”。"
    },
    {
      "claim": "自助排查方法为补水并重新安装清水箱，温水冲洗出水阀",
      "verdict": "supported",
      "evidence_index": 2,
      "reason": "片段[2]自助排查写明“补水并重新安装清水箱，温水冲洗出水阀”。"
    },
    {
      "claim": "若重启后 E07 复现，则需检查水泵",
      "verdict": "supported",
      "evidence_index": 2,
      "reason": "片段[2]需要售后写明“重启后 E07 复现，需检查水泵”。"
    },
    {
      "claim": "若重启后 E07 复现，应联系售后",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "属于“请联系售后”类兜底话术，非事实性内容。"
    },
    {
      "claim": "以上步骤全部执行后问题仍存在，请停止自助排查并联系官方售后",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "兜底售后话术，非事实性内容。"
    }
  ]
}
